ST.xhtml:p:
RTrigger(CLK := g_biU3HomeEnable OR bHomeEnable);
IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := 1;
END_IF;
IF RTrigger.Q THEN
    nHomeState := 1;
    g_boU3HomeDone := FALSE;
    bHomeDone := FALSE;
END_IF;

CASE nHomeState OF
  0:
    nHomeState := 0;
  1:
    g_U3Home.Execute := TRUE;
    IF nHomingMode = 0 THEN
      g_U3Home.HomingMode := 0;
      g_U3Home.Position := dHomePosition;
    ELSIF nHomingMode = 1 THEN
      g_U3Home.HomingMode := 5;
      g_U3Home.Position := 0.0;
    ELSIF nHomingMode = 2 THEN
      g_U3Home.HomingMode := 4;
      g_U3Home.Position := 0.0;
    ELSIF nHomingMode = 3 THEN
      (*只是去掉回零标志位*)
      g_U3Home.HomingMode := 1; 
    END_IF;
    g_U3Home.bCalibrationCam := g_bU3AxisZero;
    IF g_U3Home.Done THEN
      g_U3Home.Execute := FALSE;
       IF nHomingMode = 3 THEN
        nHomeState := 0;
      ELSE
        nHomeState := 2;
      END_IF;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nHomeState := 20;
    END_IF;
    IF g_U3Home.CommandAborted OR g_U3Home.Error THEN
      g_U3Home.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  2:
    g_U3MoveAbs.Execute := TRUE;
    g_U3MoveAbs.Position := dHomeOffset;
    g_U3MoveAbs.Velocity := dHomeVel;
    IF g_U3MoveAbs.Done THEN
      g_U3MoveAbs.Execute := FALSE;
      bHomeDone := TRUE;
      g_boU3HomeDone := TRUE;
      nHomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nHomeState := 21;
    END_IF;
  20:
    g_U3Home.Execute := FALSE;
    g_U3MoveStop.Execute := TRUE;
    IF g_U3MoveStop.Done AND g_bPlcStartBuffer THEN
      g_U3MoveStop.Execute := FALSE;
      nHomeState := 1;
    END_IF;
    IF g_U3MoveStop.CommandAborted OR g_U3MoveStop.Error THEN
      g_U3MoveStop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  21:
    g_U3Home.Execute := FALSE;
    g_U3MoveStop.Execute := TRUE;
    IF g_U3MoveStop.Done AND g_bPlcStartBuffer THEN
      g_U3MoveStop.Execute := FALSE;
      nHomeState := 2;
    END_IF;
    IF g_U3MoveStop.CommandAborted OR g_U3MoveStop.Error THEN
      g_U3MoveStop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
END_CASE;

CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    g_U3Home.Execute := TRUE;
    IF nHomingMode = 0 THEN
      g_U3Home.HomingMode := 0;
    ELSIF nHomingMode = 1 THEN
      g_U3Home.HomingMode := 5;
    ELSIF nHomingMode = 2 THEN
      g_U3Home.HomingMode := 4;
    END_IF;
    IF g_U3Home.Done THEN
      g_U3Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF g_U3Home.CommandAborted OR g_U3Home.Error THEN
      g_U3Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nHomeState := 0;
  nChangeHomeModeState := 0;
  g_boU3HomeDone := TRUE;
  g_U3MoveStop.Execute := FALSE;
  g_U3Home.Execute := FALSE;
  bHomeDone := TRUE;
END_IF;
